-- The engine's own tables (docs/store.md): each synthesis, transcription and encoding it keeps, the events it
-- publishes, and the language a voice speaks.

ALTER TABLE "voices" ADD COLUMN IF NOT EXISTS "language" text NOT NULL DEFAULT 'ko';

CREATE TABLE "voice_syntheses" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "voice_name" text NOT NULL,
  "text" text NOT NULL,
  "emotion" text,
  "state" text NOT NULL,
  "duration_ms" bigint,
  "created_at" bigint NOT NULL
);

CREATE TABLE "voice_transcriptions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "language" text NOT NULL,
  "state" text NOT NULL,
  "text" text,
  "created_at" bigint NOT NULL
);

CREATE TABLE "voice_encodings" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "state" text NOT NULL,
  "from_wav" text NOT NULL,
  "sound_path" text,
  "created_at" bigint NOT NULL
);

CREATE TABLE "voice_events" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" text NOT NULL,
  "at" bigint NOT NULL,
  "data" text NOT NULL
);
